using System.Security.Claims;using Microsoft.AspNetCore.Authentication;using Microsoft.AspNetCore.Authentication.Cookies;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using MyExpenseTracker.Api.Data;using MyExpenseTracker.Api.Models;namespace MyExpenseTracker.Api.Controllers;[ApiController,Route("api/auth")]public class AuthController(AppDbContext db,IPasswordHasher<AppUser> h):ControllerBase{[HttpPost("login")]public async Task<IActionResult> Login(LoginRequest r){var u=await db.Users.SingleOrDefaultAsync(x=>x.UserName=="Alchemist");if(u==null||string.IsNullOrWhiteSpace(u.PasswordHash))return Unauthorized();if(h.VerifyHashedPassword(u,u.PasswordHash,r.Password??"")==PasswordVerificationResult.Failed)return Unauthorized();var i=new ClaimsIdentity(CookieAuthenticationDefaults.AuthenticationScheme);i.AddClaim(new Claim(ClaimTypes.Name,u.UserName));await HttpContext.SignInAsync(CookieAuthenticationDefaults.AuthenticationScheme,new ClaimsPrincipal(i));return Ok(new{userName=u.UserName});}[HttpPost("logout")]public async Task<IActionResult> Logout(){await HttpContext.SignOutAsync();return NoContent();}[HttpGet("me")]public IActionResult Me()=>User.Identity?.IsAuthenticated==true?Ok(new{userName=User.Identity.Name}):Unauthorized();public record LoginRequest(string? Password);}